pre_request_script.code:
// Lấy credentials từ environment
const email = pm.environment.get('email');
const password = pm.environment.get('password');
const role = pm.environment.get('role');

// Log info
console.log(`\n🔐 Logging in as ${role}`);
console.log(`📧 Email: ${email}`);

// Set request body
pm.request.body = JSON.stringify({
  email: email,
  password: password
});

test_script.code:
// Check login success
if (pm.response.code === 200) {
    let responseData = pm.response.json();

    // Save token
    pm.environment.set('accessToken', responseData.accessToken);
    pm.environment.set('refreshToken', responseData.refreshToken);

    // Save user info
    if (responseData.user) {
        pm.environment.set('userId', responseData.user.id);
    }

    // Show success
    pm.test('✅ Login Success', function() {
        pm.expect(pm.response.code).to.equal(200);
    });

    console.log(`\n✅ Token saved for ${pm.environment.get('role')}`);
    console.log(`🔑 Token: ${responseData.accessToken.substring(0, 20)}...`);
} else {
    pm.test('❌ Login Failed', function() {
        pm.expect(pm.response.code).to.be.oneOf([200, 201]);
    });
    console.log(`\n❌ Login failed: ${pm.response.code}`);
}

add_this_to_login_request.code:
// Auto-save token sau login
if (pm.response.code === 200) {
    let body = pm.response.json();
    pm.environment.set('accessToken', body.accessToken);
    pm.environment.set('refreshToken', body.refreshToken);
    pm.environment.set('userId', body.user.id);

    pm.test('✅ Login thành công', function() {
        pm.expect(pm.response.code).to.equal(200);
        pm.expect(body.accessToken).to.be.a('string');
    });
}

