        pm.expect(pm.response.code).to.equal(403);
    });
} else if (pm.response.code === 200 || pm.response.code === 201) {
    pm.test(`✅ ${currentRole} có quyền`, function() {
        pm.expect(pm.response.code).to.be.oneOf([200, 201]);
    });
} else {
